// This file was generated by Prisma and updated for Next.js env conventions.
import path from "path";
import * as dotenv from "dotenv";
import { defineConfig } from "prisma/config";

// Mirror Next.js precedence: .env first, then .env.local (which wins if present).
// Prisma CLI does not read either file automatically when a config file is used.
dotenv.config({ path: path.resolve(process.cwd(), ".env") });
dotenv.config({ path: path.resolve(process.cwd(), ".env.local"), override: true });

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "npx tsx prisma/seed.ts",
  },
  datasource: {
    url: process.env["DATABASE_URL"] as string,
  },
});
